import fixture from './__fixtures__/synthetic_adapter_output.json';
import {homeNeuralPlot} from './homeNeuralChartData';
import {neuralPlot, NEURAL_METRICS, programsAt, parameterValue} from './neuralTimelineData';
import {groupState} from './neuralGroupState';
import {configurationSvg} from './contactSchematic';

// This output is generated by the real Python adapter and Prasad native decoder.
// The generator beside the fixture owns the independently synthetic input recipe.
const window = fixture.home.windows[0];
const event = fixture.observations[0];
const metric = key => NEURAL_METRICS.find(item=>item.key===key);
const range = {start:'2026-01-25',end:'2026-01-25'};

test('actual canonical decoder output retains singleton and two-point runs, all final samples and sentinel gaps',()=>{
 const panel=window.panels.find(item=>item.side==='left');
 expect(panel.segments.map(segment=>segment.points.length).sort()).toEqual([1,1,2]);
 expect(panel.segments.every(segment=>segment.end_basis==='exclusive_sample_envelope')).toBe(true);
 const result=homeNeuralPlot(panel,window,'fresh-installation-uuid');
 expect(result.observedPower).toBe(2);
 expect(result.observedAmplitude).toBe(4);
 expect(result.latestTime).toBe(1769329800);
 expect(result.traces.filter(trace=>trace.yaxis==='y').flatMap(trace=>trace.y).filter(value=>value!==null)).toEqual([12,17]);
 expect(result.traces.filter(trace=>trace.yaxis==='y2').flatMap(trace=>trace.y).filter(value=>value!==null).sort()).toEqual([1,2,3,4]);
 expect(result.traces.every(trace=>trace.connectgaps===false)).toBe(true);
 expect(result.traces.filter(trace=>trace.line?.dash==='dash')).toHaveLength(0);
 // Half-open boundaries remain meaningful even with an exclusive sample envelope.
 const clipped=homeNeuralPlot(panel,{...window,end:1769329800},'fresh-installation-uuid');
 expect(clipped.observedPower).toBe(1);expect(clipped.observedAmplitude).toBe(3);
});

test('actual serializer preserves distinct source programs, normalized units and raw contact evidence',()=>{
 const programs=programsAt(event,'fresh-installation-uuid');
 expect(programs.map(program=>program.id)).toEqual(['left:1','left:2','right:']);
 expect(programs.map(program=>parameterValue(metric('pulse_width'),program).value)).toEqual([60,90,120]);
 expect(programs.map(program=>parameterValue(metric('amplitude'),program).value)).toEqual([1,2,3]);
 expect(programs.map(program=>program.rows['Source contacts'])).toEqual(['E01-A → CAN','E02-B → CAN','E01-C → CAN']);
 const plotted=neuralPlot([event],metric('amplitude'),range,'fresh-installation-uuid');
 expect(plotted.traces.filter(trace=>trace.mode==='lines').every(trace=>trace.x.length===0)).toBe(true);
 expect(plotted.traces.filter(trace=>trace.mode==='markers').map(trace=>trace.y)).toEqual([[1],[2],[3]]);
});

test('actual geometry and side-normalized contacts render source-backed diagrams for a fresh UUID',()=>{
 const before=JSON.stringify(event);
 const plotted=neuralPlot([event],metric('contacts'),range,'fresh-installation-uuid');
 const configuration=plotted.configurations[0];
 expect(configuration.leads.map(lead=>lead.contacts.valid)).toEqual([true,true,true]);
 expect(configuration.leads.map(lead=>lead.knownGeometry)).toEqual([true,true,true]);
 const diagram=decodeURIComponent(configurationSvg(configuration,1));
 expect(diagram).toContain('1a−');expect(diagram).toContain('2b−');expect(diagram).toContain('9c−');
 expect(diagram).not.toContain('unresolved');
 const unknown=neuralPlot([{...event,lead_geometry:undefined}],metric('contacts'),range,'fresh-installation-uuid');
 expect(unknown.configurations[0].leads.every(lead=>!lead.knownGeometry)).toBe(true);
 expect(JSON.stringify(event)).toBe(before);
});

test('actual source mode and cycling stay visible without claiming open- or closed-loop delivery',()=>{
 const state=groupState(event.settings);
 expect(state.label).toBe('Recorded program type · Interleaving · Delivery state unknown · Cycling on 0.05 min / off 0.15 min');
 const plotted=neuralPlot([event],metric('mode'),range,'fresh-installation-uuid');
 expect(plotted.categories).toEqual([state.label]);
 expect(plotted.traces.filter(trace=>trace.mode==='markers').flatMap(trace=>trace.y)).toEqual([0]);
});
